#!/usr/bin/env python3
"""Street Legends backend: Pills enemy-drop item (backend / Publish).

USER SPEC (exact): item name "Pills"; sells for $200 per oz; using it
grants 50% energy for 1 minute; when collected it goes into the
player's item screen (inventory). Art is the uploaded orange pill-bottle
image, embedded below as a data-URI icon_url (the GitHub push tool
cannot carry binary PNGs, so no raw GitHub URL is used; if the client
cannot render the data URI, the row falls back to the medkit icon and
the item still functions).

READINGS (NOT the user's decisions — correctable):
USER SPEC (drop rule): Pills drop with a 1-in-6 chance EACH fight —
  a flat ~16.7% roll on every standard battle victory, 1 oz when it
  lands, any enemy type. NOT an interval counter, NOT a 1-to-6-fight gap
  system. PvP and guild-raid victories have no loot path in the snapshot
  and are not hooked.

READINGS (NOT the user's decisions — correctable):
- Use: consumes 1 oz; for 60 seconds effective max energy is base max
  x 1.5 and current energy immediately rises by 50% of base max
  (capped at the boosted max). A second use while active refreshes the
  60s timer (no stacking). When the buff expires, max returns to base
  and current energy clamps to base max at the next battle start.
- Sell: $200 per oz, 1 oz per tap, from the item screen, no prompt.

Design notes (mirroring the Grass patch; live /app may differ, hence
guards; this patch is STANDALONE — it never assumes Grass code ran):
- Inventory is player["inventory"], a list of item_id strings or dicts;
  Pills is stored as ONE stacked dict {"item_id": "pills", "qty": N,
  "unit": "oz", ...} rather than one entry per oz.
- Pills is added to ALL_ITEMS so the inventory-details endpoint returns
  it (items absent from ALL_ITEMS are invisible on the item screen). It
  is EXCLUDED from the generic random drop pool so it cannot double-drop.
- Buffs live in player["active_buffs"] as {type: "max_energy", amount,
  ...}. Pills reuses that system with an expires_at timestamp plus a
  large battles_remaining (10000) so the time expiry — not the
  per-battle decrement — is what ends it. The battle-start max-energy
  sum is made expiry-aware (buffs without expires_at are unaffected);
  this is where the +50% actually applies in combat, since start_battle
  caps current energy to buffed_max_energy.
- The generic sell endpoint pays value//2 and pops one whole entry, so
  it must NOT be used for Pills: dedicated use/sell endpoints below pay
  exactly $200/oz and decrement qty. The frontend hides the generic
  Sell/Equip buttons for Pills rows.
- Shared parts (qty/unit passthrough, buff-expiry filter) carry BOTH the
  Pills and Grass markers in their comments, so whichever patch runs
  second prints ALREADY_APPLIED instead of duplicating the code.
"""
import re, sys
from pathlib import Path

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("/app")
SRV = ROOT / "backend/server.py"

PILLS_URL = "data:image/png;base64,"

CATALOG = '''
# PILLS_ITEM_CATALOG: Pills enemy-drop item (see patch header for spec/readings).
ALL_ITEMS["pills"] = {
    "id": "pills", "name": "Pills", "category": "consumable",
    "description": "Bottle of pills. Use: +50% max energy for 60 seconds. Sells for $200 per oz.",
    "icon": "medkit", "icon_url": ''' + '"' + PILLS_URL + '"' + ''',
    "rarity": "common", "equipment_type": "consumable",
    "stats_bonus": {}, "level_requirement": 1, "value": 200,
}
'''

ROUTES = '''
# PILLS_ITEM_USE / PILLS_ITEM_SELL: dedicated Pills endpoints ($200/oz, 1 oz per sell tap).
@api_router.post("/players/{player_id}/pills/use")
async def use_pills(player_id: str):
    """Use 1 oz of Pills: +50% max energy for 60 seconds (refreshes if active)."""
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    p_idx = None
    p_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "pills":
            p_idx, p_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "pills":
            p_idx, p_qty = _i, 1
            break
    if p_idx is None or p_qty < 1:
        raise HTTPException(status_code=400, detail="No Pills in inventory")
    if p_qty <= 1:
        inv.pop(p_idx)
    elif isinstance(inv[p_idx], dict):
        inv[p_idx]["qty"] = p_qty - 1
    else:
        inv.pop(p_idx)
    stats = player.get("stats", {})
    base_max = stats.get("max_energy", 100)
    gain = int(base_max * 0.5)
    boosted_max = base_max + gain
    new_energy = min(stats.get("energy", base_max) + gain, boosted_max)
    expiry = (datetime.utcnow() + timedelta(minutes=1)).isoformat()
    buffs = [b for b in player.get("active_buffs", []) if b.get("item_id") != "pills"]
    buffs.append({
        "id": "pills_" + str(uuid.uuid4())[:8], "item_id": "pills", "name": "Pills",
        "type": "max_energy", "amount": gain, "percent": 0.5,
        "battles_remaining": 10000, "expires_at": expiry, "icon": "medkit",
    })
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv, "active_buffs": buffs, "stats.energy": new_energy}},
    )
    return {"message": "Pills used! +50% max energy for 60 seconds.", "energy": new_energy,
            "boosted_max_energy": boosted_max, "expires_at": expiry, "oz_left": p_qty - 1}


@api_router.post("/players/{player_id}/pills/sell")
async def sell_pills(player_id: str, qty: int = 1):
    """Sell Pills at $200 per oz."""
    if qty < 1:
        raise HTTPException(status_code=400, detail="Quantity must be at least 1")
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    p_idx = None
    p_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "pills":
            p_idx, p_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "pills":
            p_idx, p_qty = _i, 1
            break
    if p_idx is None or p_qty < qty:
        raise HTTPException(status_code=400, detail="Not enough Pills in inventory")
    if p_qty <= qty:
        inv.pop(p_idx)
        left = 0
    elif isinstance(inv[p_idx], dict):
        inv[p_idx]["qty"] = p_qty - qty
        left = p_qty - qty
    else:
        inv.pop(p_idx)
        left = 0
    gained = 200 * qty
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv}, "$inc": {"cash": gained}},
    )
    return {"message": f"Sold {qty} oz of Pills for ${gained}", "cash_gained": gained, "oz_left": left}

'''


def main():
    if not SRV.exists():
        print("PILLS_ITEM_ERROR: backend/server.py not found (run from /app)")
        return 1
    src = SRV.read_text(errors="ignore")
    orig = src
    landed = []

    # 1. Catalog entry.
    if "PILLS_ITEM_CATALOG" in src:
        print("PILLS_ITEM_CATALOG_ALREADY_APPLIED"); landed.append("catalog")
    else:
        anchor = "# Apply icon URLs to all equipment items"
        fallback = "ALL_ITEMS.update(LEVEL_ACCESSORIES)"
        if anchor in src:
            src = src.replace(anchor, CATALOG.strip() + "\n\n" + anchor, 1)
            print("PILLS_ITEM_CATALOG_OK"); landed.append("catalog")
        elif fallback in src:
            src = src.replace(fallback, fallback + "\n" + CATALOG.strip(), 1)
            print("PILLS_ITEM_CATALOG_OK"); landed.append("catalog")
        else:
            print("WARNING: catalog anchor not found - Pills NOT added to ALL_ITEMS (item will be invisible on the item screen)")

    # 2. Exclude Pills from the generic random drop pool (no double-drop).
    if 'item["id"] != "pills"' in src:
        print("PILLS_ITEM_POOL_EXCLUDE_ALREADY_APPLIED"); landed.append("pool")
    else:
        grass_line = 'if item["id"] != "grass" and item["level_requirement"] <= enemy["level"] + 2'
        plain_line = 'if item["level_requirement"] <= enemy["level"] + 2'
        if grass_line in src:
            src = src.replace(grass_line, 'if item["id"] != "grass" and item["id"] != "pills" and item["level_requirement"] <= enemy["level"] + 2', 1)
            print("PILLS_ITEM_POOL_EXCLUDE_OK"); landed.append("pool")
        elif plain_line in src:
            src = src.replace(plain_line, 'if item["id"] != "pills" and item["level_requirement"] <= enemy["level"] + 2', 1)
            print("PILLS_ITEM_POOL_EXCLUDE_OK"); landed.append("pool")
        else:
            print("WARNING: generic drop-pool anchor not found - Pills may ALSO drop from the generic pool, so it could double-drop")

    # 3. Dedicated 1-in-6-per-fight drop on monster-battle victory.
    if "PILLS_ITEM_DROP" in src:
        print("PILLS_ITEM_DROP_ALREADY_APPLIED"); landed.append("drop")
    else:
        loot_at = src.find('combat_log.append(f"Loot drop: {dropped_item[\'name\']}!")')
        if loot_at == -1:
            print("WARNING: victory loot anchor not found - Pills drop NOT added (no defeat hook)")
        else:
            upd_at = src.find("# Update player stats", loot_at)
            if upd_at == -1:
                print("WARNING: victory update anchor not found - Pills drop NOT added (no defeat hook)")
            else:
                drop = ('            # PILLS_ITEM_DROP: USER SPEC - 1-in-6 chance EACH fight (flat ~16.7% roll), 1 oz, any monster enemy.\n'
                        '            if random.random() < (1/6):\n'
                        '                _p_inv = player.get("inventory", [])\n'
                        '                _p_idx = next((i for i, _it in enumerate(_p_inv) if isinstance(_it, dict) and _it.get("item_id") == "pills"), None)\n'
                        '                if _p_idx is None:\n'
                        '                    _p_inv.append({"item_id": "pills", "qty": 1, "unit": "oz", "durability": 100, "max_durability": 100})\n'
                        '                else:\n'
                        '                    _p_inv[_p_idx]["qty"] = _p_inv[_p_idx].get("qty", 1) + 1\n'
                        '                await db.players.update_one({"id": player["id"]}, {"$set": {"inventory": _p_inv}})\n'
                        '                rewards["items"] = (rewards.get("items") or []) + ["pills"]\n'
                        '                combat_log.append("Loot drop: Pills (1 oz)!")\n'
                        )
                src = src[:upd_at] + drop + src[upd_at:]
                print("PILLS_ITEM_DROP_OK"); landed.append("drop")

    # 4. Inventory-details qty/unit passthrough (shared with Grass; dual marker
    #    so whichever patch runs second skips instead of duplicating).
    if "PILLS_ITEM_QTY" in src or "GRASS_ITEM_QTY" in src:
        print("PILLS_ITEM_QTY_ALREADY_APPLIED"); landed.append("qty")
    else:
        anchor = 'item_with_durability["inventory_index"] = idx'
        if anchor in src:
            add = ('\n            # PILLS_ITEM_QTY / GRASS_ITEM_QTY: pass stacked quantities through to the item screen.\n'
                   '            if inv_item.get("qty") is not None:\n'
                   '                item_with_durability["qty"] = inv_item["qty"]\n'
                   '            if inv_item.get("unit"):\n'
                   '                item_with_durability["unit"] = inv_item["unit"]')
            src = src.replace(anchor, anchor + add, 1)
            print("PILLS_ITEM_QTY_OK"); landed.append("qty")
        else:
            print("WARNING: inventory-details anchor not found - oz count will NOT reach the item screen (Pills will show without a quantity)")

    # 5. Buff expiry filtering at battle start (shared with Grass; dual marker).
    if "PILLS_ITEM_EXPIRY" in src or "GRASS_ITEM_EXPIRY" in src:
        print("PILLS_ITEM_EXPIRY_ALREADY_APPLIED"); landed.append("expiry")
    else:
        old_hp = 'buff_hp = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_health")'
        old_en = 'buff_en = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_energy")'
        if old_hp in src and old_en in src:
            new_hp = ('# PILLS_ITEM_EXPIRY / GRASS_ITEM_EXPIRY: buffs past expires_at no longer count (buffs without expires_at are unaffected).\n'
                      '    _pills_now_iso = datetime.utcnow().isoformat()\n'
                      '    def _pills_buff_live(b):\n'
                      '        _exp = b.get("expires_at")\n'
                      '        return (not _exp) or (str(_exp) >= _pills_now_iso)\n'
                      '    buff_hp = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_health" and _pills_buff_live(b))')
            new_en = 'buff_en = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_energy" and _pills_buff_live(b))'
            src = src.replace(old_hp, new_hp, 1).replace(old_en, new_en, 1)
            print("PILLS_ITEM_EXPIRY_OK"); landed.append("expiry")
        else:
            print("WARNING: battle-start buff anchor not found - expired Pills buffs would keep counting in battle; ENERGY HOOK NOT VERIFIED, need a live snippet of the start_battle buff calculation (max_energy sum)")

    # 6. Use + sell endpoints.
    if "PILLS_ITEM_USE" in src and "PILLS_ITEM_SELL" in src:
        print("PILLS_ITEM_ENDPOINTS_ALREADY_APPLIED"); landed.append("endpoints")
    else:
        inc = "app.include_router(api_router)"
        if inc in src and "datetime" in src and "timedelta" in src and "uuid" in src:
            src = src.replace(inc, ROUTES.strip() + "\n\n\n" + inc, 1)
            print("PILLS_ITEM_ENDPOINTS_OK"); landed.append("endpoints")
        else:
            print("WARNING: router anchor or datetime/timedelta/uuid imports not found - Pills use/sell endpoints NOT added")

    if src == orig:
        print("PILLS_ITEM_ALREADY_APPLIED")
        return 0
    try:
        compile(src, "server.py", "exec")
    except SyntaxError as e:
        print("PILLS_ITEM_SYNTAX_FAIL: %s (file NOT written)" % e)
        return 1
    SRV.write_text(src)
    if len(landed) == 6:
        print("PILLS_ITEM_OK")
    else:
        print("PILLS_ITEM_PARTIAL: " + ",".join(landed))
    return 0

if __name__ == "__main__":
    sys.exit(main())
